  Section MAIN.
    Variables (mm : word -> option byte) (fjunk : list byte).
    Hypothesis MIm : mem_inv asegs mm.
    Hypothesis E1m : bytes_at asegs mm (bv_unsigned a0) (map b8 (e ++ 0 :: rest1)).
    Hypothesis E2m : bytes_at asegs mm (bv_unsigned a1) (map b8 (t ++ 0 :: rest2)).
    Hypothesis FR1 : FRAME mm.
    Hypothesis FR : rw_cells asegs mm (bv_unsigned sp + -2192) [CB 2088 fjunk].
    Hypothesis STm : stk asegs mm lo (bv_unsigned sp + -2192).
    Hypothesis MU : munch W m mm.
    Hypothesis WM : wmono asegs m mm.
    Hypothesis G1 : rw_cells asegs mm 1586912 [C8 (Z_to_bv 64 1636088)].
    Hypothesis CB1 : rw_cells asegs mm 1636088 [C8 (Z_to_bv 64 2147450880)].
    Hypothesis G2 : rw_cells asegs mm 1586920 [C8 (Z_to_bv 64 1639400)].
    Hypothesis G3 : rw_cells asegs mm 1586928 [C8 (Z_to_bv 64 1639408)].
    Hypothesis G4 : rw_cells asegs mm 1586936 [C8 (Z_to_bv 64 1639392)].
    Hypothesis CB4 : rw_cells asegs mm 1639392 [C8 (Z_to_bv 64 (2 ^ 47 - 1)); C8 (Z_to_bv 64 0); C8 (Z_to_bv 64 0)].
    Hypothesis SV2m : stk asegs mm (sh (hull_lo p2)) (sh (hull_hi (p2 + lnt + 1))).
    Hypothesis SV1m : stk asegs mm (sh (hull_lo p1)) (sh (hull_hi (p1 + lne + 1))).
    Hypothesis G6 : rw_cells asegs mm 1586896 [C8 (Z_to_bv 64 2232872)].
    Hypothesis CFSm : rw_cells asegs mm 2233117 [C1 (Z_to_bv 8 0)].
    Hypothesis ISCm : rw_cells asegs mm 2233122 [C1 (Z_to_bv 8 1)].

    Lemma asc_cl : forall (k : nat) (j : Z) x1 x5 x10 x11 x12 x13 x14 x15 x16 x17 x21 x22 x23 x24 x25 x26 x27,
      Z.to_nat (lne - j) = k -> 0 <= j -> j <= lne -> j <= lnt ->
